from datetime import datetime, timezone

def hours_between(a, b):
    def parse_ts(s):
        # Handle 'Z' suffix by replacing with '+00:00'
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'

        # Parse the full string including timezone
        # Format: YYYY-MM-DDTHH:MM:SS[.ffffff][+HH:MM|-HH:MM|Z]
        # We need to handle optional microseconds and timezone
        try:
            # Try parsing with timezone first if present
            if '+' in s[19:] or (s[19:].count('-') > 0 and s[19:].startswith('-')):
                # Check for timezone offset
                if 'Z' in s:
                    s = s.replace('Z', '+00:00')
                # Find the timezone part
                # Split at the timezone indicator
                if '+' in s:
                    idx = s.rfind('+')
                elif '-' in s[19:]:
                    idx = s.rfind('-', 19)
                else:
                    idx = len(s)

                dt_part = s[:idx]
                tz_part = s[idx:]

                # Parse datetime part
                # Handle microseconds if present
                if '.' in dt_part:
                    dt = datetime.strptime(dt_part, "%Y-%m-%dT%H:%M:%S.%f")
                else:
                    dt = datetime.strptime(dt_part, "%Y-%m-%dT%H:%M:%S")

                # Parse timezone offset
                if tz_part:
                    if tz_part == 'Z':
                        tz = timezone.utc
                    else:
                        # Parse +HH:MM or -HH:MM
                        sign = 1 if tz_part[0] == '+' else -1
                        tz_str = tz_part[1:]
                        hours, minutes = map(int, tz_str.split(':'))
                        offset = sign * (hours * 3600 + minutes * 60)
                        tz = timezone(offset)
                    dt = dt.replace(tzinfo=tz)
                else:
                    # No timezone info, assume UTC
                    dt = dt.replace(tzinfo=timezone.utc)
                return dt
            else:
                # No timezone info, assume UTC
                dt = datetime.strptime(s, "%Y-%m-%dT%H:%M:%S")
                return dt.replace(tzinfo=timezone.utc)
        except ValueError:
            # Fallback for simple parsing without timezone
            dt = datetime.strptime(s[:19], "%Y-%m-%dT%H:%M:%S")
            return dt.replace(tzinfo=timezone.utc)

    ta = parse_ts(a)
    tb = parse_ts(b)

    # If both are timezone aware, compute difference in UTC
    if ta.tzinfo is not None and tb.tzinfo is not None:
        diff = tb - ta
    else:
        # If one or both are naive, assume they are in the same timezone (UTC)
        diff = tb - ta

    return abs(diff.total_seconds()) / 3600
