def handle_create_user(body):
    if not isinstance(body, dict):
        return (400, {"errors": {"body": "must be an object"}})

    errors = {}

    # Validate name
    name = body.get("name")
    if name is None or not isinstance(name, str):
        errors["name"] = "must be a non-empty string"
    else:
        stripped_name = name.strip()
        if not stripped_name:
            errors["name"] = "must be a non-empty string"
        else:
            body["name"] = stripped_name

    # Validate age
    age = body.get("age")
    if age is None:
        errors["age"] = "is required"
    elif not isinstance(age, int) or isinstance(age, bool):
        errors["age"] = "must be an integer"
    elif age < 0 or age > 150:
        errors["age"] = "must be between 0 and 150"
    else:
        body["age"] = age

    # Validate email
    email = body.get("email")
    if email is not None:
        if not isinstance(email, str):
            errors["email"] = "must be a string"
        else:
            if email.count("@") != 1:
                errors["email"] = "must contain exactly one '@'"
            else:
                parts = email.split("@")
                if not parts[0] or not parts[1]:
                    errors["email"] = "must have non-empty parts around '@'"
                else:
                    body["email"] = email

    if errors:
        return (422, {"errors": errors})

    return (201, {"name": body["name"], "age": body["age"], "email": body.get("email")})
